package com.citacloud.springboot.contacloud.app.services;
import com.citacloud.springboot.contacloud.app.dto.*;import com.citacloud.springboot.contacloud.app.repositories.NotaDebitoVentaRepository;
import org.junit.jupiter.api.*;import org.apache.pdfbox.Loader;import org.apache.pdfbox.text.PDFTextStripper;
import java.math.BigDecimal;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class NotaDebitoVentaPdfServiceTest{
 final NotaDebitoVentaRepository repo=mock(NotaDebitoVentaRepository.class);final NotaDebitoVentaPdfService pdf=new NotaDebitoVentaPdfService(repo);
 static NotaDebitoVentaDocumento fixture(int count){
 var c=NotaCreditoVentaPdfServiceTest.fixture(count);
 return new NotaDebitoVentaDocumento(c.id(),"NDV-PRUEBA-000001",c.fecha(),c.emitidaEn(),c.emitidaPor(),UUID.randomUUID(),c.factura(),c.fechaFactura(),"Emitida",c.condicionPago(),c.sucursalId(),c.clienteId(),c.cliente(),c.identificacion(),UUID.randomUUID(),c.moneda(),UUID.randomUUID(),"Cargo adicional","Cargo autorizado. Datos de prueba sin efecto financiero real.",
 c.lineas().stream().map(l->new NotaDebitoVentaDocumento.Linea(l.descripcion(),l.cantidad(),l.precio(),l.bruto(),l.descuento(),null,l.impuestoNombre(),l.tasa(),l.impuesto(),l.total())).toList(),c.subtotal(),c.descuento(),c.impuesto(),c.total(),new BigDecimal("100"),new BigDecimal("100").add(c.total()),c.empresa(),c.empresaLegal(),c.rnc(),c.direccionEmpresa(),c.telefono(),c.correoEmpresa(),c.logoEmpresa());
 }
 static NotaDebitoVentaCicloDto state(boolean voided){return new NotaDebitoVentaCicloDto(voided?"VOIDED":"CONFIRMED",0,!voided,null,null,null);}
 @Test void pdfGrandeUsaSnapshotSinMarcaYAnuladaEsInequivoca()throws Exception{for(boolean voided:List.of(false,true)){byte[] bytes=pdf.render(fixture(1),state(voided));try(var doc=Loader.loadPDF(bytes)){String text=new PDFTextStripper().getText(doc);assertThat(text).contains("NOTA DE DÉBITO","NDV-PRUEBA-000001","DOCUMENTO AFECTADO","TOTAL DOP");assertThat(text).doesNotContain("ContaCloud","NOTA DE CRÉDITO");if(voided)assertThat(text).contains("ANULADA");else assertThat(text).doesNotContain("ANULADA");assertThat((doc.getPage(0).getRotation()%180==90?doc.getPage(0).getMediaBox().getHeight():doc.getPage(0).getMediaBox().getWidth())).isEqualTo(842f);assertThat(doc.getDocumentCatalog().getOpenAction()).isNull();NotaCreditoVentaPdfServiceTest.assertBounds(doc);}NotaCreditoVentaPdfServiceTest.save(voided?"NotaDebito-Anulada-PRUEBA":"NotaDebito-Emitida-PRUEBA",bytes);}}
 @Test void multipaginaConservaEncabezadosYTotales()throws Exception{var bytes=pdf.render(fixture(70),state(false));try(var doc=Loader.loadPDF(bytes)){assertThat(doc.getNumberOfPages()).isGreaterThan(2);String text=new PDFTextStripper().getText(doc);assertThat(text.split("TOTAL USD",-1)).hasSize(2);assertThat(text).contains("Producto 70");NotaCreditoVentaPdfServiceTest.assertBounds(doc);}}
 @Test void reimprimirSoloLeeSinDuplicarEfectos(){var d=fixture(1);when(repo.documento(d.id())).thenReturn(d);when(repo.ciclo(d.id(),false)).thenReturn(state(false));pdf.generar(d.id());pdf.generar(d.id());verify(repo,times(2)).documento(d.id());verify(repo,times(2)).ciclo(d.id(),false);verifyNoMoreInteractions(repo);}
 @Test void descripcionEsDatoSinAccionesPdf()throws Exception{var mapper=tools.jackson.databind.json.JsonMapper.builder().build();var d=fixture(1);@SuppressWarnings("unchecked") Map<String,Object> data=mapper.readValue(mapper.writeValueAsString(d),Map.class);data.put("descripcion","<script>alert(1)</script> javascript:alert(1) /Launch");try(var doc=Loader.loadPDF(pdf.render(mapper.convertValue(data,NotaDebitoVentaDocumento.class),state(false)))){assertThat(doc.getDocumentCatalog().getOpenAction()).isNull();for(var page:doc.getPages())assertThat(page.getAnnotations()).isEmpty();}}

 @Test void contadoConsumidorFinalMuestraCondicionPagosYCambioSinDeuda()throws Exception{
  var mapper=tools.jackson.databind.json.JsonMapper.builder().build();var original=fixture(1);@SuppressWarnings("unchecked") Map<String,Object> values=mapper.readValue(mapper.writeValueAsString(original),Map.class);
  values.put("condicionPago","Contado");values.put("clienteId",null);values.put("cliente","Consumidor Final");values.put("identificacion",null);values.put("condicionNota","CASH");values.put("pagado",original.total());values.put("saldoNota",BigDecimal.ZERO);values.put("recibido",original.total().add(BigDecimal.TEN));values.put("cambio",BigDecimal.TEN);
  values.put("pagos",List.of(new NotaDebitoVentaDocumento.Pago(UUID.randomUUID(),UUID.randomUUID(),"Efectivo","CASH",BigDecimal.TEN,new BigDecimal("20"),BigDecimal.TEN,null,UUID.randomUUID(),UUID.randomUUID(),"Caja"),new NotaDebitoVentaDocumento.Pago(UUID.randomUUID(),UUID.randomUUID(),"Tarjeta","CREDIT_CARD",new BigDecimal("4.16"),null,BigDecimal.ZERO,"REF-TEST",UUID.randomUUID(),null,"Banco")));
  var cash=mapper.convertValue(values,NotaDebitoVentaDocumento.class);var bytes=pdf.render(cash,state(false));try(var doc=Loader.loadPDF(bytes)){String text=new PDFTextStripper().getText(doc);assertThat(text).contains("Consumidor Final","Condición de la nota: Contado","FORMA DE PAGO","Efectivo","Tarjeta","TOTAL PAGADO","Cambio");assertThat(text).doesNotContain("EFECTO FINANCIERO EN LA EMISIÓN","RNC/Cédula:");NotaCreditoVentaPdfServiceTest.assertBounds(doc);}NotaCreditoVentaPdfServiceTest.save("NotaDebito-Contado-ConsumidorFinal-PRUEBA",bytes);
  try(var doc=Loader.loadPDF(pdf.render(original,state(false)))){String text=new PDFTextStripper().getText(doc);assertThat(text).contains("Condición de la nota: Crédito");assertThat(text).doesNotContain("FORMA DE PAGO","TOTAL PAGADO");}
 }
}
